// range(3) -> [0,1,2]; range(2,5) -> [2,3,4]
function range(a, b) {
	const [start, end] = b === undefined ? [0, a] : [a, b];
	const out = [];
	for (let i = start; i < end; i++) out.push(i);
	return out;
}
module.exports = { range };

